from typing import Set

def spread(config: Set[int]) -> Set[int]:
    """spread(S) = {0} union {n+1 : n in S}."""
    return {0} | {n + 1 for n in config}

def spread_iterate(k: int) -> Set[int]:
    config: Set[int] = set()
    for _ in range(k):
        config = spread(config)
    return config

def demo_finite_orbit(max_k: int = 10) -> None:
    """spread^[k]({}) = {0, 1, ..., k-1}: a wave advancing at unit speed."""
    for k in range(max_k + 1):
        cfg = spread_iterate(k)
        assert cfg == set(range(k)), (k, cfg)
        print(f"k={k:2d}: {sorted(cfg)}  (matches {{0,...,{k-1}}})")

if __name__ == "__main__":
    demo_finite_orbit()

