from typing import Set

def spread(config: Set[int]) -> Set[int]:
    return {0} | {n + 1 for n in config}

def spread_iterate(k: int) -> Set[int]:
    config: Set[int] = set()
    for _ in range(k):
        config = spread(config)
    return config

def stage_omega(bound: int) -> Set[int]:
    """Limit stage omega = union of all finite stages (restricted to cells<bound)."""
    result: Set[int] = set()
    for n in range(bound + 1):
        result |= spread_iterate(n)
    return {c for c in result if c < bound}

def demo_completion_at_omega(bound: int = 20) -> None:
    """At stage omega every cell is on: the union of all finite stages is N."""
    omega_cfg = stage_omega(bound)
    assert omega_cfg == set(range(bound))
    print(f"stage omega (cells < {bound}) = {sorted(omega_cfg)} = full line")
    print("closure ordinal = omega: completes at the first infinite stage.")

if __name__ == "__main__":
    demo_completion_at_omega()

from typing import Set, Tuple, List

def grid_spread(config: Set[Tuple[int, int]], width: int) -> Set[Tuple[int, int]]:
    """A grid rule with closure ordinal omega^2: row i+1 fills only once row i
    is complete.  Each row is a spreading automaton needing omega steps."""
    result: Set[Tuple[int, int]] = set(config)
    result.add((0, 0))
    for (r, c) in config:
        if c + 1 < width:
            result.add((r, c + 1))
    max_row = max((r for (r, _) in config), default=0)
    for r in range(max_row + 2):
        below_done = all((r - 1, c) in config for c in range(width)) if r > 0 else True
        if below_done:
            result.add((r, 0))
    return {(r, c) for (r, c) in result if 0 <= c < width}

def demo_grid_beyond_omega(width: int = 5, steps: int = 40) -> None:
    """Row i completes only after omega*i steps: closure ordinal omega^2."""
    config: Set[Tuple[int, int]] = set()
    done: List[int] = []
    for _ in range(steps):
        config = grid_spread(config, width)
        for r in range(width):
            if r not in done and all((r, c) in config for c in range(width)):
                done.append(r)
    print(f"width={width}, {steps} steps: completed rows {sorted(done)}")
    print("finishing infinitely many rows in sequence needs omega^2.")

if __name__ == "__main__":
    demo_grid_beyond_omega()

